def reprendre_pdl(apps, schema_editor):
    """Le n° PDL déjà saisi dans la fiche du lot est repris dans ses baux."""
    Bail = apps.get_model("patrimoine", "Bail")
    for bail in Bail.objects.exclude(lot__pdl="").select_related("lot"):
        bail.pdl_electricite = bail.lot.pdl
        bail.save(update_fields=["pdl_electricite"])


